import {
  MeshStandardNodeMaterial,
  color,
  positionLocal,
  vec3,
  dot,
  normalize,
  smoothstep,
  mix,
} from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, Color, Vector3 } = ctx.THREE;

  // Root container
  const container = new Group();

  // Create stage background (7x6 units at z=-2.5) to prevent void
  const bgGeo = new PlaneGeometry(7.5, 6.5);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
  });

  // Background procedural vertical gradient from spec: #101017 (0) to #1a1a22 (1)
  const bgGrad = smoothstep(-2.5, 2.5, positionLocal.y);
  bgMat.colorNode = mix(color('#101017'), color('#1a1a22'), bgGrad);

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.z = -2.5;
  container.add(bgMesh);

  // Local lights setup to illuminate the machined metal chamfers & surface
  // Key light (top-right-front)
  const keyLight = new DirectionalLight('#e8ecf2', 1.3);
  keyLight.position.set(3, 4, 3);
  container.add(keyLight);

  // Rim light opposite (bottom-left-front)
  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-3, -3, 2);
  container.add(rimLight);

  // Layout geometries & constants
  const dominantW = 3.25;
  const dominantH = 3.5;
  const secondaryW = 2.0;
  const secondaryH = 1.625;
  const gutter = 0.25;
  const depth = 0.06;
  const bevel = 0.04;

  // Custom node material supporting a 135-deg engineered diagonal gradient on face + hard-stop sheen band
  function createMachinedMaterial() {
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
    });

    // 135 deg direction vector in local space
    const dir = normalize(vec3(-1.0, 1.0, 0.0));
    const dist = dot(positionLocal.xyz, dir);

    // Baseline gradient: #101017 -> #1a1a22
    const baseGradient = smoothstep(-2.0, 2.0, dist);
    const gradColor = mix(color('#101017'), color('#1a1a22'), baseGradient);

    // Hard-stop machined sheen band 0.15 wide at 40% (dist value around -0.4 to 0.4 depending on scale)
    // Add 6% value boost (#101017 + 6% or gradient boost)
    const bandMask = smoothstep(-0.2, -0.15, dist).mul(smoothstep(0.0, -0.05, dist));
    const finalColor = mix(gradColor, gradColor.add(color('#1c1c2b')), bandMask);

    mat.colorNode = finalColor;
    return mat;
  }

  // Create bevelled box manually with multiple groups or simple box with PBR
  // Since we require shallow extruded slab with chamfers, we can model each cell with simplified box geometry
  function createCellBox(w, h, d) {
    const geo = new BoxGeometry(w, h, d);
    const mat = createMachinedMaterial();
    return new Mesh(geo, mat);
  }

  // Cell structures inside a direct array
  const cells = [];
  const textGroup = new Group();
  container.add(textGroup);

  // Set up cell configuration data
  const cellConfigs = [
    {
      // Dominant cell (Left Column, spans full height)
      id: 'dominant',
      w: dominantW,
      h: dominantH,
      x: -dominantW / 2 - gutter / 2,
      y: 0,
      value: '0.002 mm',
      valueType: 'valueLarge',
      label: 'Case tolerance, CNC pass',
    },
    {
      // Upper secondary cell (Right Column, Top)
      id: 'sec_top',
      w: secondaryW,
      h: secondaryH,
      x: secondaryW / 2 + gutter / 2,
      y: secondaryH / 2 + gutter / 2,
      value: '38 h',
      valueType: 'value',
      label: 'Power reserve, NA-01',
    },
    {
      // Lower secondary cell (Right Column, Bottom)
      id: 'sec_bottom',
      w: secondaryW,
      h: secondaryH,
      x: secondaryW / 2 + gutter / 2,
      y: -(secondaryH / 2 + gutter / 2),
      value: '214',
      valueType: 'value',
      label: 'Components per calibre',
    },
  ];

  const cellMeshes = [];
  const cleanups = [];

  // Build each cell
  cellConfigs.forEach((c) => {
    const cellGroup = new Group();
    cellGroup.position.set(c.x, c.y, 0);

    // Machined base
    const slab = createCellBox(c.w, c.h, depth);
    cellGroup.add(slab);

    // Emissive #ff2a38 Accent Tick top-left
    const tickMat = new MeshStandardNodeMaterial({
      color: '#ff2a38',
      emissive: '#ff2a38',
      emissiveIntensity: 1.3,
    });
    const tickGeo = new BoxGeometry(0.4, 0.05, 0.02);
    const tick = new Mesh(tickGeo, tickMat);
    // Align left-top relative to cell bounds
    tick.position.set(-c.w / 2 + 0.4, c.h / 2 - 0.3, depth / 2 + 0.01);
    cellGroup.add(tick);

    // Text assets allocation
    const isDominant = c.valueType === 'valueLarge';
    const valFontSize = isDominant ? 0.62 : 0.34;
    const valText = ctx.fontAtlas.createText(c.value, {
      fontSize: valFontSize,
      color: '#e8ecf2',
      align: 'left',
    });

    // Label mapping (Caption-like JetBrains Mono font context)
    const labelText = ctx.fontAtlas.createText(c.label, {
      fontSize: 0.09, // ~18px visual height scale
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 12,
    });

    // Position text inside container relative to center pivot of slab
    // Padding offsets
    const paddingX = -c.w / 2 + 0.4;
    valText.position.set(paddingX, c.h / 2 - (isDominant ? 1.5 : 0.8), depth / 2 + 0.02);
    labelText.position.set(paddingX, valText.position.y - 0.5, depth / 2 + 0.02);

    cellGroup.add(valText);
    cellGroup.add(labelText);

    container.add(cellGroup);
    cellMeshes.push(cellGroup);

    // Interaction handlers per cell
    let activeTl = null;

    cellGroup.userData.onPointerOver = () => {
      if (activeTl) activeTl.kill();
      activeTl = gsap.timeline();
      // press-down scale 1.0 to 0.97 in 120ms
      activeTl.to(cellGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power1.out',
      });
    };

    cellGroup.userData.onPointerOut = () => {
      if (activeTl) activeTl.kill();
      activeTl = gsap.timeline();
      // release weighted-settle 1.04 to 1.0 over 900ms
      activeTl.to(cellGroup.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.3,
        ease: 'power2.out',
      }).to(cellGroup.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.6,
        ease: 'power4.out',
      });
    };

    // Keep reference for interactive dispatcher mapping
    cells.push({ mesh: cellGroup, bounds: { xMin: c.x - c.w/2, xMax: c.x + c.w/2, yMin: c.y - c.h/2, yMax: c.y + c.h/2 } });
  });

  // Header Caption above grid
  // Left-aligned at x = -2.75, y = top bounds of dominant column + offset
  const headerCaption = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 0.12, // scaled Mono
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 12,
  });
  headerCaption.position.set(-2.75, 2.25, 0.05);
  container.add(headerCaption);

  // Entrance timelines (Staggered cards, fade-up per cell)
  const masterTl = gsap.timeline();
  cellMeshes.forEach((mesh, index) => {
    mesh.position.y -= 0.2;
    mesh.scale.set(0, 0, 0);

    masterTl.to(mesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.5,
      ease: 'back.out(1.2)',
    }, index * 0.08);

    masterTl.to(mesh.position, {
      y: cellConfigs[index].y,
      duration: 0.5,
      ease: 'power3.out',
    }, index * 0.08);
  });

  // Dispatch raycast interactions inside the system via classic canvas logic mapping
  let hoveredCell = null;
  const onPointerMove = (evt) => {
    if (!evt.intersection) return;
    const localPt = container.worldToLocal(evt.intersection.point.clone());
    let currentHover = null;
    for (const cell of cells) {
      if (
        localPt.x >= cell.bounds.xMin &&
        localPt.x <= cell.bounds.xMax &&
        localPt.y >= cell.bounds.yMin &&
        localPt.y <= cell.bounds.yMax
      ) {
        currentHover = cell;
        break;
      }
    }

    if (currentHover !== hoveredCell) {
      if (hoveredCell) hoveredCell.mesh.userData.onPointerOut();
      if (currentHover) currentHover.mesh.userData.onPointerOver();
      hoveredCell = currentHover;
    }
  };

  const onPointerLeave = () => {
    if (hoveredCell) {
      hoveredCell.mesh.userData.onPointerOut();
      hoveredCell = null;
    }
  };

  // Wire interactions to container userdata handlers
  container.userData.handlers = {
    pointermove: onPointerMove,
    pointerleave: onPointerLeave,
  };

  container.userData.cleanup = () => {
    masterTl.kill();
    bgGeo.dispose();
    bgMat.dispose();
    keyLight.dispose();
    rimLight.dispose();
  };

  return container;
}
